{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "IAM policy allows actions on all resources (*)",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "HIGH",
      "explanation": "The IAM policy allows actions on all resources (`Resource = "*"`), which can lead to privilege escalation or unintended access. This is overly permissive and should be scoped to specific resources."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:StartSession",
          "ssm:DescribeSessions",
          "ssm:GetConnectionStatus",
          "ssm:DescribeInstanceProperties",
          "ssm:TerminateSession",
          "ssm:ResumeSession"
        ]
        Resource = [
          "arn:aws:ec2:region:account-id:instance/instance-id",
          "arn:aws:ssm:region:account-id:session/session-id"
        ]
      },
    ]
  })
}",
  "fix_summary": "Scoped the IAM policy's `Resource` field to specific ARNs for EC2 instances and SSM sessions, replacing the overly permissive wildcard (`*`)."
}
